   \"url\": \"git+https://github.com/hyhmrright/brooks-lint.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/hyhmrright/brooks-lint/issues\"\n  },\n  \"keywords\": [\n    \"agent-skills\",\n    \"code-review\",\n    \"architecture\",\n    \"technical-debt\",\n    \"codex\",\n    \"claude-code\",\n    \"cursor\",\n    \"copilot\",\n    \"deepseek-harness\",\n    \"dsh-plugin\"\n  ],\n  \"bin\": {\n    \"brooks-lint\": \"bin/brooks-lint.mjs\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  }\n}\n"
